// Error Bars — Comparison, route: jsx
// Source: original:gaps/error-bars
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from errorBars ----
// Treatment-effect estimates from eight A/B experiments: conversion uplift in
// percent with a 95% confidence interval. Several intervals cross zero — the
// chart's argument is that those experiments proved nothing either way.
const experimentEffects: { name: string; value: number; lo: number; hi: number }[] = [
  { name: 'Onboarding rewrite', value: 4.6, lo: 2.1, hi: 7.1 },
  { name: 'One-click checkout', value: 3.2, lo: 1.4, hi: 5.0 },
  { name: 'Price anchoring', value: 2.1, lo: -0.4, hi: 4.6 },
  { name: 'Email cadence', value: 1.3, lo: -0.9, hi: 3.5 },
  { name: 'New badge design', value: 0.4, lo: -1.8, hi: 2.6 },
  { name: 'Free shipping banner', value: -0.2, lo: -2.0, hi: 1.6 },
  { name: 'Dark mode default', value: -1.1, lo: -3.3, hi: 1.1 },
  { name: 'Autoplay video', value: -2.7, lo: -5.2, hi: -0.2 }
];

const MARGIN = { top: 16, right: 16, bottom: 36, left: 150 };

/** A point estimate per category with its interval bounds. */
export type Data = { name: string; value: number; lo: number; hi: number }[];

export default function ErrorBars({ data = experimentEffects, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.55);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const sorted = useMemo(() => [...data].sort((a, b) => b.value - a.value), [data]);

  const x = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([d3.min(sorted, (d) => d.lo) ?? 0, d3.max(sorted, (d) => d.hi) ?? 1])
        .nice()
        .range([0, innerWidth]),
    [sorted, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleBand<string>()
        .domain(sorted.map((d) => d.name))
        .range([0, innerHeight])
        .padding(0.4),
    [sorted, innerHeight]
  );

  const xTicks: Tick[] = useMemo(
    () => x.ticks(Math.max(3, Math.round(innerWidth / 70))).map((v) => ({ value: String(v), offset: x(v) })),
    [x, innerWidth]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Point estimates with confidence intervals per experiment, sorted by effect size around a zero reference line"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <line x1={x(0)} x2={x(0)} y1={0} y2={innerHeight} stroke="var(--text)" strokeWidth={1.5} strokeDasharray="4 3" />
        {sorted.map((d) => {
          const center = (y(d.name) ?? 0) + y.bandwidth() / 2;
          return (
            <g key={d.name}>
              <line x1={x(d.lo)} x2={x(d.hi)} y1={center} y2={center} stroke="var(--muted)" strokeWidth={2} />
              <line x1={x(d.lo)} x2={x(d.lo)} y1={center - 4} y2={center + 4} stroke="var(--muted)" strokeWidth={2} />
              <line x1={x(d.hi)} x2={x(d.hi)} y1={center - 4} y2={center + 4} stroke="var(--muted)" strokeWidth={2} />
              <circle cx={x(d.value)} cy={center} r={4.5} fill="var(--accent)" />
              <text x={-10} y={center} dy="0.32em" textAnchor="end" fontSize={11} fill="var(--text)">
                {d.name}
              </text>
            </g>
          );
        })}
      </g>
    </svg>
  );
}
